class Solution {
  public int minimumPossibleSum(int n, int target) {
    final long MOD = 1_000_000_007L;
    // take 1..m (no two of them sum to target), then continue from target upwards
    long m = Math.min(n, target / 2);
    long rest = n - m;
    long sum = m * (m + 1) / 2 + rest * target + rest * (rest - 1) / 2;
    return (int) (sum % MOD);
  }
}
